function renderCalendar(){const days=['Domenica','Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato'],s=schedule(),closed=JSON.parse(cfg.settings.closed_dates||'[]');$('#view').innerHTML=`<div class="admin-card" id="calendarOverview"><div class="row between tableflex"><div><h3>Programmazione ritiri</h3><p class="muted">Vedi gli ordini e blocca uno slot specifico senza chiudere tutta la giornata.</p></div><div class="field"><label>Giorno da controllare</label><input type="date" id="calendarDay" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}"></div></div><div id="calendarSlots" class="slot-overview">Caricamento...</div></div><div class="admin-card">${heading('Disponibilità del ritiro','Definisci una o più fasce per ogni giorno. Inserisci due orari separati da un trattino (es. 18:30-22:30), un intervallo per riga. Lascia vuoto per chiuso.')}<form id="scheduleForm">${days.map((d,i)=>`<div class="field"><label>${d}</label><textarea rows="2" id="day-${i}" placeholder="Chiuso">${(s[i]||[]).map(r=>r.join('-')).join('\n')}</textarea></div>`).join('')}<button class="btn">Salva giorni e orari</button></form></div><div class="admin-card">${heading('Giorni di chiusura straordinaria','Inserisci una data per riga nel formato AAAA-MM-GG.')}<form id="closedForm"><div class="field"><label>Date chiuse</label><textarea id="closedDates" rows="5" placeholder="2026-12-25">${closed.join('\n')}</textarea></div><button class="btn">Salva chiusure</button></form></div><div class="admin-card">${heading('Capacità e tempi','Quanti ordini puoi ricevere per ogni fascia e con quanto anticipo?')}<form id="capacityForm" class="tableflex"><div class="field"><label>Intervallo slot (minuti)</label><select id="slotMinutes">${[5,10,15,20,30,60].map(v=>`<option value="${v}" ${+cfg.settings.slot_minutes===v?'selected':''}>${v} minuti</option>`).join('')}</select></div><div class="field"><label>Max ordini per slot</label><input id="slotCap" type="number" min="1" max="100" value="${cfg.settings.slot_capacity}"></div><div class="field"><label>Anticipo minimo (minuti)</label><input id="lead" type="number" min="0" max="720" value="${cfg.settings.lead_minutes}"></div><div class="field"><label>Giorni prenotabili avanti</label><input id="ahead" type="number" min="1" max="60" value="${cfg.settings.max_days_ahead}"></div><button class="btn">Salva parametri</button></form></div>`;
$('#scheduleForm').onsubmit=async e=>{e.preventDefault();try{const obj={};for(let i=0;i<7;i++){const raw=$(`#day-${i}`).value.trim();obj[i]=raw?raw.split('\n').map(x=>x.trim().split(/\s*-\s*/)).filter(x=>x.length===2):[];}await saveSettings({pickup_schedule:obj});flash('Orari aggiornati');renderCalendar();}catch(ex){flash(ex.message);}};$('#closedForm').onsubmit=async e=>{e.preventDefault();try{await saveSettings({closed_dates:$('#closedDates').value.split(/\n/).map(x=>x.trim()).filter(Boolean)});flash('Chiusure salvate');renderCalendar();}catch(ex){flash(ex.message);}};$('#capacityForm').onsubmit=async e=>{e.preventDefault();try{await saveSettings({slot_minutes:+$('#slotMinutes').value,slot_capacity:+$('#slotCap').value,lead_minutes:+$('#lead').value,max_days_ahead:+$('#ahead').value});flash('Disponibilità aggiornata');renderCalendar();}catch(ex){flash(ex.message);}};}
async function initCalendarOverview(){const day=$('#calendarDay');if(!day)return;day.onchange=loadCalendarDay;await loadCalendarDay();}
async function loadCalendarDay(){const input=$('#calendarDay'),el=$('#calendarSlots');if(!input||!el)return;const d=input.value;el.textContent='Caricamento...';try{const r=await api('/api/admin/calendar-summary?from='+encodeURIComponent(d)+'&to='+encodeURIComponent(d));const blocked=r.blocked||{},arr=new Set(blocked[d]||[]),counts={};for(const x of r.rows){const key=x.time;counts[key]??={qty:0,total:0};if(['pending','accepted','preparing','ready'].includes(x.status))counts[key].qty+=x.qty;counts[key].total+=x.total||0;}
 const day=new Date(d+'T12:00:00Z').getUTCDay(),ranges=schedule()[day]||[],step=Number(cfg.settings.slot_minutes)||15,capacity=Number(cfg.settings.slot_capacity)||5,opts=[];
 for(const [start,end] of ranges){let a=Number(start.slice(0,2))*60+Number(start.slice(3)),b=Number(end.slice(0,2))*60+Number(end.slice(3));for(let t=a;t<=b;t+=step){const time=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');opts.push(time);}}
 el.innerHTML=opts.length?`<div class="calendar-grid">${opts.map(t=>`<div class="calendar-slot ${arr.has(t)?'blocked':''}"><strong>${t}</strong><span class="muted">${counts[t]?.qty||0} / ${capacity} ordini</span><span class="muted">${eur(counts[t]?.total||0)} richiesti</span><button class="btn small ${arr.has(t)?'light':'outline'}" data-slot="${t}">${arr.has(t)?'Riapri slot':'Blocca slot'}</button></div>`).join('')}</div>`:'<p class="muted">Nessuna fascia impostata per questo giorno.</p>';
 el.querySelectorAll('[data-slot]').forEach(b=>b.onclick=async()=>{const time=b.dataset.slot,updated=new Set(arr);if(updated.has(time))updated.delete(time);else updated.add(time);const all={...blocked,[d]:[...updated]};try{await saveSettings({blocked_slots:all});flash('Disponibilità slot aggiornata');loadCalendarDay();}catch(e){flash(e.message);}});
 }catch(e){el.textContent='Errore calendario: '+e.message;}}
function renderSettings(){$('#view').innerHTML=`<div class="admin-card"><h3>Attivazione ordini online</h3><p class="muted">Il sito è inizialmente chiuso alle ordinazioni finché non completi tutte le configurazioni.</p><div class="row between"><span class="tag ${cfg.settings.orders_enabled==='true'?'success':'warn'}">${cfg.settings.orders_enabled==='true'?'Ordini attivi':'Ordini disattivati'}</span><button class="btn ${cfg.settings.orders_enabled==='true'?'danger':''}" id="toggleOrders">${cfg.settings.orders_enabled==='true'?'Disattiva ordini':'Attiva ordini'}</button></div></div><div class="admin-card">${heading('Dati e testi pubblici','Le informazioni sono visibili ai clienti nel sito e nei messaggi.')}<form id="siteSettings">${[['hero_title','Titolo homepage'],['hero_subtitle','Sottotitolo homepage'],['restaurant_address','Indirizzo ritiro'],['restaurant_phone','Telefono ristorante'],['restaurant_email','Email di contatto (non imposta notifiche)'],['instagram_url','Link Instagram (https://www.instagram.com/...)'],['facebook_url','Link Facebook (https://www.facebook.com/...)'],['notice','Avviso clienti'],['whatsapp_message_footer','Frase finale WhatsApp']].map(([id,title])=>`<div class="field"><label for="${id}">${title}</label><input id="${id}" maxlength="500" value="${esc(cfg.settings[id]||'')}"></div>`).join('')}<div class="field"><label>Porzioni salse consentite</label><select id="sauceMax">${[1,2,3,4,5].map(v=>`<option value="${v}" ${+cfg.settings.sauce_max_quantity===v?'selected':''}>${v}${v===2?' (normale e abbondante)':''}</option>`).join('')}</select></div><button class="btn">Salva impostazioni</button></form></div>${imageSettingsHtml()}<div class="admin-card"><h3>Privacy e protezione dati</h3><p class="muted">Completa l'informativa, falla verificare dal responsabile del ristorante e abilita la presa visione prima di accettare ordini.</p><form id="privacySettings"><div class="field"><label>Titolare del trattamento (ragione sociale)</label><input name="privacy_controller" value="${esc(cfg.settings.privacy_controller||'')}" required></div><div class="field"><label>Contatto privacy (email)</label><input type="email" name="privacy_contact" value="${esc(cfg.settings.privacy_contact||'')}" required></div><div class="field"><label>Conservazione configurata (giorni, da gestire operativamente)</label><input type="number" min="30" max="1095" name="privacy_retention_days" value="${esc(cfg.settings.privacy_retention_days||'365')}"></div><label class="row"><input type="checkbox" name="privacy_policy_enabled" ${cfg.settings.privacy_policy_enabled==='true'?'checked':''}> Confermo che informativa, allergeni e processi sono stati verificati</label><p><a href="/privacy.html" target="_blank">Visualizza informativa</a></p><button class="btn">Salva configurazione privacy</button></form><hr><p class="muted">Pulizia manuale dati: rimuove in lotti di massimo 300 gli ordini conclusi oltre il periodo configurato. Prima esporta o conserva quanto necessario per obblighi legali e amministrativi.</p><button class="btn small outline danger" id="cleanupPrivacy">Elimina dati scaduti</button></div><div class="admin-card">${heading('Notifiche email','Per attivare realmente gli avvisi, occorrono RESEND_API_KEY, EMAIL_FROM e ORDER_NOTIFY_EMAIL tra i segreti/variabili di Cloudflare.')}<p class="muted">La notifica sonora funziona quando il gestionale è aperto. Per consentire l'audio al browser, premi il pulsante di prova.</p><button class="btn light" id="testSound">🔔 Prova suono</button></div>`;
$('#toggleOrders').onclick=async()=>{const enabled=cfg.settings.orders_enabled!=='true';if(enabled&&!confirm('Hai verificato orari, prezzi, ingredienti, allergeni, indirizzo e informativa privacy? Attivare gli ordini ora?'))return;try{await saveSettings({orders_enabled:enabled});renderSettings();flash('Stato ordini aggiornato');}catch(e){flash(e.message);}};$('#siteSettings').onsubmit=async e=>{e.preventDefault();const value={sauce_max_quantity:Number($('#sauceMax').value)};for(const name of ['hero_title','hero_subtitle','restaurant_address','restaurant_phone','restaurant_email','instagram_url','facebook_url','notice','whatsapp_message_footer'])value[name]=$('#'+name).value;try{await saveSettings(value);renderSettings();flash('Impostazioni salvate');}catch(ex){flash(ex.message);}};$('#testSound').onclick=()=>playAlert();bindImageSettings();$('#cleanupPrivacy').onclick=async()=>{if(!confirm('Eliminare irreversibilmente gli ordini conclusi oltre il periodo scelto? Verifica prima eventuali obblighi legali di conservazione.'))return;try{const r=await api('/api/admin/privacy-cleanup',{method:'POST',body:JSON.stringify({confirm:'ELIMINA_ORDINI_SCADUTI'})});flash(r.deleted+' ordini scaduti eliminati'+(r.more_possible?' (ci sono altri lotti)':''));}catch(e){flash(e.message);}};$('#privacySettings').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await saveSettings({privacy_controller:f.elements.privacy_controller.value,privacy_contact:f.elements.privacy_contact.value,privacy_retention_days:Number(f.elements.privacy_retention_days.value),privacy_policy_enabled:f.elements.privacy_policy_enabled.checked});flash('Configurazione privacy aggiornata');renderSettings();}catch(err){flash(err.message);}};}

function imageSettingsHtml(){const details=[['hero','Immagine principale','Immagine grande a destra nella homepage'],['logo','Logo','Logo nell’intestazione del sito'],['secondary','Immagine secondaria','Fotografia nel footer sopra ai recapiti']];return `<div class="admin-card"><h3>Immagini del sito</h3><p class="muted">Carica JPG, PNG o WebP: il browser ridimensiona e ottimizza il file prima del salvataggio nel database D1. Si possono sostituire o ripristinare le immagini senza modificare GitHub.</p><div class="site-image-grid">${details.map(([slot,title,desc])=>`<div class="site-image-card"><div class="image-preview"><img src="/api/public/image?slot=${slot}&v=${encodeURIComponent(cfg.image_versions?.[slot]||'default')}" alt="Anteprima ${title}" data-preview="${slot}" onerror="this.style.visibility='hidden'"></div><h4>${title}</h4><p class="muted">${desc}</p><label class="btn small image-upload-label" for="upload-${slot}">Carica immagine</label><input type="file" id="upload-${slot}" data-upload="${slot}" accept="image/jpeg,image/png,image/webp" hidden><button type="button" class="btn small outline" data-remove-image="${slot}" ${cfg.image_versions?.[slot]?'':'disabled'}>Ripristina</button><p class="muted" id="image-status-${slot}" role="status"></p></div>`).join('')}</div></div>`;}
async function optimizeImage(file,slot){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usa JPG, PNG o WebP');if(file.size>12*1024*1024)throw Error('File originale troppo grande (max 12 MB)');const img=await createImageBitmap(file);try{const max=slot==='ingredient'?500:slot==='logo'?800:slot==='hero'?1600:1100;const scale=Math.min(1,max/Math.max(img.width,img.height));const can=document.createElement('canvas');can.width=Math.max(1,Math.round(img.width*scale));can.height=Math.max(1,Math.round(img.height*scale));can.getContext('2d').drawImage(img,0,0,can.width,can.height);let blob;for(const quality of [.83,.7,.55,.4]){blob=await new Promise(r=>can.toBlob(r,'image/webp',quality));if(blob&&blob.size<=(slot==='ingredient'?300000:480000))break;}if(!blob||blob.size>(slot==='ingredient'?300000:480000))throw Error('Immagine troppo pesante: scegli una foto più piccola');const buffer=await blob.arrayBuffer();const bytes=new Uint8Array(buffer);let output='';for(let i=0;i<bytes.length;i+=8192)output+=String.fromCharCode(...bytes.subarray(i,i+8192));return {mime:'image/webp',data:btoa(output)};}finally{img.close();}}
function bindImageSettings(){document.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const slot=input.dataset.upload,el=document.getElementById('image-status-'+slot),f=input.files?.[0];if(!f)return;input.disabled=true;el.textContent='Ottimizzazione e caricamento in corso…';try{const encoded=await optimizeImage(f,slot);await api('/api/admin/site-image',{method:'POST',body:JSON.stringify({slot,...encoded})});await loadBootstrap();renderSettings();flash('Immagine '+slot+' aggiornata');}catch(e){el.textContent=e.message;}finally{input.disabled=false;}});document.querySelectorAll('[data-remove-image]').forEach(btn=>btn.onclick=async()=>{if(!confirm('Ripristinare l’immagine originale?'))return;try{await api('/api/admin/site-image',{method:'DELETE',body:JSON.stringify({slot:btn.dataset.removeImage})});await loadBootstrap();renderSettings();flash('Immagine ripristinata');}catch(e){flash(e.message);}});}
function datesForStats(period){const d=new Date(),fmt=x=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(x),end=fmt(d);let from=end;if(period==='7'||period==='30'||period==='90'||period==='365'){d.setDate(d.getDate()-(Number(period)-1));from=fmt(d);}else if(period==='month')from=end.slice(0,7)+'-01';else if(period==='all')from='2020-01-01';return {from,to:end};}
async function renderStatistics(){const pre=statsPeriod||'30',range=datesForStats(pre);$('#view').innerHTML=`<div class="ops-top"><div><div class="eyebrow">ANALISI ATTIVITÀ</div><h2>Statistiche Ilèa Poké</h2><p class="muted">Dati reali degli ordini registrati, raggruppati per data di ritiro.</p></div><button class="btn small outline" id="statsRefresh">↻ Aggiorna</button></div><div class="admin-card filters"><div class="field"><label>Periodo</label><select id="statsPeriod">${[['today','Oggi'],['7','Ultimi 7 giorni'],['30','Ultimi 30 giorni'],['90','Ultimi 90 giorni'],['month','Mese corrente'],['365','Ultimi 365 giorni'],['all','Dall’inizio']].map(([v,l])=>`<option value="${v}" ${v===pre?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Dal</label><input type="date" id="statsFrom" value="${range.from}"></div><div class="field"><label>Al</label><input type="date" id="statsTo" value="${range.to}"></div><button class="btn small" id="statsApply">Applica</button></div><div id="statsContent" class="admin-card">Caricamento statistiche…</div>`;
$('#statsPeriod').onchange=e=>{statsPeriod=e.target.value;renderStatistics()};$('#statsRefresh').onclick=()=>fetchStatistics($('#statsFrom').value,$('#statsTo').value);$('#statsApply').onclick=()=>fetchStatistics($('#statsFrom').value,$('#statsTo').value);await fetchStatistics(range.from,range.to);}
let statsPeriod='30';
async function fetchStatistics(from,to){
 const dest=$('#statsContent');if(!dest)return;dest.className='admin-card';dest.textContent='Calcolo statistiche…';
 try{
  if(!from||!to||from>to)throw Error('Scegli un intervallo di date valido.');
  const r=await api('/api/admin/stats?'+new URLSearchParams({from,to})),t=r.totals;
  const n=v=>Number(v)||0,pct=(v,d)=>d?((100*v)/d).toLocaleString('it-IT',{maximumFractionDigits:1})+'%':'0%';
  const total=n(t.orders),delivered=n(t.delivered),cancelled=n(t.cancelled),rejected=n(t.rejected),noShow=n(t.no_show),pending=n(t.pending),accepted=n(t.accepted);
  const statuses=[['Consegnati',delivered,'#3d7354'],['Da consegnare',accepted,'#7697ae'],['In attesa',pending,'#ddb46c'],['Non ritirati',noShow,'#c96b52'],['Annullati',cancelled,'#9d9fa2'],['Rifiutati',rejected,'#8b6e78']];
  const statusSum=statuses.reduce((sum,x)=>sum+x[1],0),missing=Math.max(0,total-statusSum);
  if(missing)statuses.push(['Altri stati',missing,'#aab3aa']);
  const donut=total?(()=>{let current=0;return statuses.filter(x=>x[1]>0).map((x)=>{const start=current;current+=100*x[1]/total;return `${x[2]} ${start.toFixed(3)}% ${current.toFixed(3)}%`;}).join(',');})():'#e9eee8 0% 100%';
  const card=(label,value,description)=>`<div class="stats-kpi"><span>${label}</span><strong>${value}</strong><small>${description}</small></div>`;
  const days=(r.by_day||[]).slice(-30).map(x=>({date:x.date,orders:n(x.orders),paid:n(x.paid_cents)}));
  const maxDay=Math.max(1,...days.map(x=>x.orders));
  const w=760,h=240,padL=38,padR=16,padTop=18,padBottom=42,innerW=w-padL-padR,innerH=h-padTop-padBottom;
  const pts=days.map((x,i)=>({x:padL+(days.length<=1?innerW/2:i*innerW/(days.length-1)),y:padTop+innerH-(x.orders/maxDay)*innerH,n:x.orders,date:x.date}));
  const line=pts.map((q,i)=>(i?'L':'M')+q.x.toFixed(1)+' '+q.y.toFixed(1)).join(' ');
  const area=line?line+` L ${pts.at(-1).x.toFixed(1)} ${padTop+innerH} L ${pts[0].x.toFixed(1)} ${padTop+innerH} Z`:'';
  const grid=[0,.25,.5,.75,1].map(f=>`<g><line x1="${padL}" y1="${padTop+innerH*(1-f)}" x2="${w-padR}" y2="${padTop+innerH*(1-f)}" stroke="#e4eae2"/><text x="${padL-9}" y="${padTop+innerH*(1-f)+4}" text-anchor="end" font-size="11" fill="#778576">${Math.round(maxDay*f)}</text></g>`).join('');
  const ticks=pts.filter((_,i)=>i===0||i===pts.length-1||i%Math.max(1,Math.ceil(pts.length/7))===0).map(q=>`<text x="${q.x}" y="${h-12}" text-anchor="middle" font-size="11" fill="#6d7c6c">${esc(q.date.slice(5).replace('-','/'))}</text>`).join('');
  const chart=days.length?`<div class="stats-svg-wrap"><svg class="stats-line-chart" role="img" aria-label="Andamento degli ordini per data" viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="ilea-stats-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#648b6a" stop-opacity=".22"/><stop offset="1" stop-color="#648b6a" stop-opacity=".01"/></linearGradient></defs>${grid}<path d="${area}" fill="url(#ilea-stats-fill)"/><path d="${line}" fill="none" stroke="#3d6850" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${pts.map(q=>`<circle cx="${q.x}" cy="${q.y}" r="4" fill="#3d6850"><title>${esc(q.date)}: ${q.n} ordini</title></circle>`).join('')}${ticks}</svg></div>`:'<p class="muted">Nessun ordine nel periodo selezionato.</p>';
  const top=(r.top_ingredients||[]).slice(0,12),maxIng=Math.max(1,...top.map(x=>n(x.count)));
  const ranks=top.length?top.map((x,i)=>`<div class="stats-rank"><span class="stats-rank-name">${i+1}. ${esc(x.name)} <small>${esc(x.category)}</small></span><span class="stats-rank-track"><span style="width:${100*n(x.count)/maxIng}%"></span></span><b>${n(x.count)}</b></div>`).join(''):'<p class="muted">Nessun dato nel periodo.</p>';
  const hourData=r.by_hour||[],hourMax=Math.max(1,...hourData.map(x=>n(x.count)));
  const hourly=hourData.length?hourData.map(x=>`<div class="hour-row"><b>${esc(x.hour)}:00</b><span><i style="width:${100*n(x.count)/hourMax}%"></i></span><strong>${n(x.count)}</strong></div>`).join(''):'<p class="muted">Nessun orario rilevato.</p>';
  const accounted=statuses.reduce((sum,x)=>sum+x[1],0);
  dest.className='stats-v8';dest.innerHTML=`<div class="stats-kpi-grid">${card('Incassi registrati',eur(n(t.paid_cents)),'Pagamenti segnati come incassati')}${card('Valore degli ordini validi',eur(n(t.requested_cents)),'Esclusi annullati, rifiutati e non ritirati')}${card('Ordini ricevuti',total,'Tutti gli stati nel periodo')}${card('Poké ordinate',n(t.bowls),'Include gli ordini non consegnati')}${card('Ordini consegnati',delivered,pct(delivered,total)+' del totale')}${card('Non ritirati',noShow,pct(noShow,total)+' del totale')}${card('Ordini da consegnare',accepted,'Confermati e ancora aperti')}${card('Pagamenti da registrare',n(t.unpaid_delivered),'Ordini consegnati non segnati come pagati')}${card('Valore medio ordine valido',eur((n(t.requested_cents))/Math.max(1,total-cancelled-rejected-noShow)),'Valore validi / numero ordini validi')}${card('Ritiri in ritardo',n(t.uncollected_overdue),'Non ancora consegnati oltre l’orario')}${card('WhatsApp aperti',n(t.whatsapp_opened),'Apertura, non invio certificato')}${card('Ordini annullati',cancelled+rejected,'Annullati e rifiutati')}</div>
  <div class="stats-charts-v8"><section class="admin-card"><h3>Andamento ordini</h3><p class="muted">Fino agli ultimi 30 giorni con ordini nell’intervallo</p>${chart}</section><section class="admin-card"><h3>Distribuzione degli esiti</h3><p class="muted">Categorie distinte: nessun ordine contato due volte</p><div class="stats-donut-layout"><div class="stats-donut" style="background:conic-gradient(${donut})"><div><strong>${total}</strong><span>ordini</span></div></div><div class="stats-legend">${statuses.filter(x=>x[1]>0).map(x=>`<div><i style="background:${x[2]}"></i><span>${x[0]}</span><b>${x[1]} <small>(${pct(x[1],total)})</small></b></div>`).join('')}${!total?'<p>Nessun ordine nel periodo.</p>':''}</div></div><small class="muted">Totale categorie: ${accounted} su ${total} ordini.</small></section></div>
  <div class="stats-charts-v8"><section class="admin-card"><h3>Ingredienti più scelti</h3><p class="muted">Numero di porzioni selezionate, esclusi gli ordini annullati, rifiutati e non ritirati.</p><div class="stats-ranks">${ranks}</div></section><section class="admin-card"><h3>Orari più richiesti</h3><p class="muted">Numero di ordini per ora di ritiro, inclusi tutti gli stati.</p><div class="stats-hours">${hourly}</div></section></div><div class="admin-card"><p class="muted stats-footnote">Le cifre sono ricavate dagli ordini registrati nel database per data di ritiro; gli incassi sono pagamenti segnati manualmente nel gestionale, non fatturato fiscale certificato. Gli ordini non ritirati sono conteggiati soltanto quando contrassegnati esplicitamente come tali.</p></div>`;
 }catch(e){dest.className='admin-card';dest.textContent='Impossibile caricare le statistiche: '+e.message;}
}


async function showOrderEvents(id){try{const r=await api('/api/admin/events?id='+encodeURIComponent(id));const rows=r.events||[];const dlg=document.createElement('dialog');dlg.className='ilea-dialog';dlg.innerHTML=`<h2>Cronologia ordine ${esc(id)}</h2>${rows.map(x=>`<p><strong>${esc(x.event_type)}</strong> · ${esc(x.created_at)}<br><span class="muted">${esc(x.old_value||'—')} → ${esc(x.new_value||'—')}</span></p>`).join('')||'<p class="muted">Nessun evento precedente disponibile.</p>'}<button class="btn block" id="eventClose">Chiudi</button>`;document.body.append(dlg);dlg.showModal();dlg.querySelector('#eventClose').onclick=()=>dlg.close();dlg.onclose=()=>dlg.remove();}catch(e){flash(e.message);}}
async function renderCustomers(){$('#view').innerHTML='<div class="admin-card"><h2>Clienti e storico</h2><p class="muted">Storico per recapito. Accesso riservato al titolare, non usare questi dati per marketing senza presupposti appropriati.</p><input class="input" id="customerSearch" placeholder="Cerca nome o telefono"><div id="customerList">Caricamento…</div></div>';try{const r=await api('/api/admin/customers');const paint=()=>{const term=($('#customerSearch')?.value||'').toLowerCase();$('#customerList').innerHTML=r.customers.filter(c=>[c.name,c.phone].some(x=>String(x).toLowerCase().includes(term))).map(c=>`<div class="history-item"><div><strong>${esc(c.name)}</strong> <small>${esc(c.phone)}</small><small>${c.orders} ordini · ${c.delivered} consegnati · ${c.no_show} non ritirati · ${eur(c.paid_cents)} incassati</small><small>Ultimo ordine: ${esc(c.last_order?.slice(0,10))}</small></div></div>`).join('')||'<p>Nessun cliente trovato</p>';};$('#customerSearch').oninput=paint;paint();}catch(e){$('#customerList').textContent=e.message;}}
async function renderClosing(){$('#view').innerHTML=`<div class="admin-card"><h2>Chiusura giornaliera</h2><p class="muted">Riepilogo operativo degli ordini, non certificazione fiscale.</p><div class="field"><label>Giorno</label><input type="date" id="closingDate" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}"></div><button class="btn" id="runClosing">Calcola giornata</button><div id="closingResult"></div></div>`;const update=async()=>{try{const d=await api('/api/admin/daily-close?date='+encodeURIComponent($('#closingDate').value));$('#closingResult').innerHTML=`<div class="stats">${[['Ordini',d.orders],['Poké',d.bowls],['Consegnati',d.delivered],['Non ritirati',d.no_show],['Annullati',d.cancelled],['Consegnati da incassare',d.unpaid],['Incassi registrati',eur(d.paid_cents)]].map(([k,v])=>`<div class="stat"><span class="muted">${k}</span><strong>${v}</strong></div>`).join('')}</div><button class="btn light" id="closingCSV">Esporta riepilogo CSV</button>`;$('#closingCSV').onclick=()=>{const values=[['Dato','Valore'],...Object.entries(d)];const csv='\ufeff'+values.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='ilea-chiusura-'+d.date+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};}catch(e){$('#closingResult').textContent=e.message;}};$('#runClosing').onclick=update;await update();}
// Aggiungiamo le sezioni senza cambiare gli altri file della pagina admin.
for(const [key,label] of [['customers','👥 Clienti'],['closing','📒 Chiusura']]){if(!document.querySelector('#nav [data-section="'+key+'"]')){const b=document.createElement('button');b.dataset.section=key;b.textContent=label;$('#nav').append(b);}}
const nav=$('#nav');if(nav){const settingsButton=nav.querySelector('[data-section="settings"]');if(settingsButton)nav.append(settingsButton);}
$('#loginForm').onsubmit=login;$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(b.dataset.section));$('#refresh').onclick=async()=>{await loadBootstrap();await fetchOrders();if(section!=='orders')navigate(section);};$('#logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST'});location.reload();};
(async()=>{try{await api('/api/admin/me');await showApp();}catch{$('#login').classList.remove('hidden');}})();
setInterval(async()=>{if(!$('#dashboard').classList.contains('hidden'))await fetchOrders();},12000);

